import { z } from "zod";

const contactSchema = z.object({
  name: z.string().min(1, "Name is required"),
  email: z.string().email("Invalid email address"),
  message: z.string().min(1, "Message is required"),
});

export default function ContactForm() {
  async function submitContact(formData: FormData) {
    "use server";

    const rawData = {
      name: formData.get("name"),
      email: formData.get("email"),
      message: formData.get("message"),
    };

    const validatedFields = contactSchema.safeParse(rawData);

    if (!validatedFields.success) {
      console.error("Validation errors:", validatedFields.error.flatten().fieldErrors);
      // In a real app, you would return these errors to the UI
      return {
        errors: validatedFields.error.flatten().fieldErrors,
      };
    }

    console.log("Contact form submitted successfully:", validatedFields.data);
    return { success: true };
  }

  return (
    <div style={{ maxWidth: "400px", margin: "20px 0", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
      <h2>Contact Us</h2>
      <form action={submitContact} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        <div style={{ display: "flex", flexDirection: "column", gap: "5px" }}>
          <label htmlFor="name">Name</label>
          <input 
            type="text" 
            id="name" 
            name="name" 
            placeholder="Your Name"
            required 
            style={{ padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
          />
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: "5px" }}>
          <label htmlFor="email">Email</label>
          <input 
            type="email" 
            id="email" 
            name="email" 
            placeholder="your@email.com"
            required 
            style={{ padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
          />
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: "5px" }}>
          <label htmlFor="message">Message</label>
          <textarea 
            id="message" 
            name="message" 
            rows={4} 
            placeholder="Your message..."
            required 
            style={{ padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
          />
        </div>

        <button 
          type="submit"
          style={{ 
            padding: "10px", 
            backgroundColor: "#0070f3", 
            color: "white", 
            border: "none", 
            borderRadius: "4px", 
            cursor: "pointer",
            fontWeight: "bold"
          }}
        >
          Send Message
        </button>
      </form>
    </div>
  );
}

